<?php
/**
 * Tests for the two parts of the plugin where a mistake costs money: the amount
 * normaliser and the signature verifier.
 *
 * Deliberately dependency-free, with no PHPUnit and no WordPress, so it runs in a
 * bare PHP container:
 *
 *   docker run --rm -v "$PWD:/app" -w /app php:8.3-cli \
 *     php plugins/woocommerce/tests/run-tests.php
 *
 * `fixtures.json`, when present, holds signatures generated by the server's own
 * TypeScript implementation. Verifying those here is the only thing that proves the
 * two languages agree, which is exactly where a webhook integration breaks.
 *
 * @package KeetaCheckout
 */

declare( strict_types = 1 );

define( 'KEETA_CHECKOUT_TESTING', true );

require_once __DIR__ . '/../includes/class-keeta-checkout-amount.php';
require_once __DIR__ . '/../includes/class-keeta-checkout-signature.php';

final class Tests {

	private int $passed = 0;
	private array $failures = array();

	public function check( string $name, bool $condition, string $detail = '' ): void {
		if ( $condition ) {
			$this->passed++;
			return;
		}
		$this->failures[] = $name . ( '' === $detail ? '' : ': ' . $detail );
	}

	public function same( string $name, $expected, $actual ): void {
		$this->check(
			$name,
			$expected === $actual,
			sprintf( 'expected %s, got %s', var_export( $expected, true ), var_export( $actual, true ) )
		);
	}

	/** Assert that running `$fn` throws, and return the exception's reason or message. */
	public function throws( string $name, callable $fn ): ?string {
		try {
			$fn();
		} catch ( Keeta_Checkout_Signature_Exception $error ) {
			$this->passed++;
			return $error->reason;
		} catch ( Throwable $error ) {
			$this->passed++;
			return $error->getMessage();
		}
		$this->failures[] = $name . ': expected it to throw, but it returned';
		return null;
	}

	public function report(): int {
		foreach ( $this->failures as $failure ) {
			fwrite( STDERR, "FAIL  " . $failure . "\n" );
		}
		printf(
			"%d passed, %d failed\n",
			$this->passed,
			count( $this->failures )
		);
		return array() === $this->failures ? 0 : 1;
	}
}

$t = new Tests();

/* ---------------------------------------------------------------- amounts -- */

$t->same( 'a plain total passes through', '12.50', Keeta_Checkout_Amount::normalise( '12.50' ) );
$t->same( 'an integer total', '13', Keeta_Checkout_Amount::normalise( 13 ) );
$t->same( 'an integer string', '13', Keeta_Checkout_Amount::normalise( '13' ) );
$t->same( 'a float total loses no digits', '12.5', Keeta_Checkout_Amount::normalise( 12.5 ) );
$t->same( 'a float with two decimals', '12.99', Keeta_Checkout_Amount::normalise( 12.99 ) );
$t->same( 'a tiny float avoids scientific notation', '0.0000000001', Keeta_Checkout_Amount::normalise( 1.0e-10 ) );

// A store configured with a comma decimal separator.
$t->same( 'a comma decimal separator', '12.50', Keeta_Checkout_Amount::normalise( '12,50' ) );
// Thousands separators, in both locale conventions.
$t->same( 'comma grouping, dot decimal', '1234.50', Keeta_Checkout_Amount::normalise( '1,234.50' ) );
$t->same( 'dot grouping, comma decimal', '1234.50', Keeta_Checkout_Amount::normalise( '1.234,50' ) );
$t->same( 'several comma groups', '1234567', Keeta_Checkout_Amount::normalise( '1,234,567' ) );
$t->same( 'several dot groups', '1234567', Keeta_Checkout_Amount::normalise( '1.234.567' ) );
$t->same( 'a space as grouping', '1234.50', Keeta_Checkout_Amount::normalise( '1 234.50' ) );
$t->same( 'a non-breaking space as grouping', '1234.50', Keeta_Checkout_Amount::normalise( "1\u{00A0}234.50" ) );

$t->same( 'a currency symbol is dropped', '12.50', Keeta_Checkout_Amount::normalise( '€12.50' ) );
$t->same( 'surrounding whitespace', '12.50', Keeta_Checkout_Amount::normalise( "  12.50 \n" ) );
$t->same( 'a leading plus', '12.50', Keeta_Checkout_Amount::normalise( '+12.50' ) );
$t->same( 'a bare decimal point gains a zero', '0.5', Keeta_Checkout_Amount::normalise( '.5' ) );
$t->same( 'a trailing decimal point is dropped', '12', Keeta_Checkout_Amount::normalise( '12.' ) );
$t->same( 'leading zeros are kept, the server accepts them', '007.50', Keeta_Checkout_Amount::normalise( '007.50' ) );

// Nothing is ever rounded: many decimals survive, and the server decides.
$t->same( 'many decimals survive', '0.000000000000000001', Keeta_Checkout_Amount::normalise( '0.000000000000000001' ) );
$t->same( 'a long whole number survives', '123456789012345678901234567890', Keeta_Checkout_Amount::normalise( '123456789012345678901234567890' ) );

$t->throws( 'a negative total', static fn() => Keeta_Checkout_Amount::normalise( '-1.00' ) );
$t->throws( 'a zero total', static fn() => Keeta_Checkout_Amount::normalise( '0.00' ) );
$t->throws( 'a zero integer', static fn() => Keeta_Checkout_Amount::normalise( 0 ) );
$t->throws( 'an empty total', static fn() => Keeta_Checkout_Amount::normalise( '' ) );
$t->throws( 'a whitespace total', static fn() => Keeta_Checkout_Amount::normalise( '   ' ) );
$t->throws( 'a non-numeric total', static fn() => Keeta_Checkout_Amount::normalise( 'free' ) );
$t->throws( 'scientific notation', static fn() => Keeta_Checkout_Amount::normalise( '1e3' ) );
$t->throws( 'two decimal points', static fn() => Keeta_Checkout_Amount::normalise( '1.2.3' ) );

// Grouping has to be shaped like grouping. These once became 123 and 1234, which
// would have charged a customer a hundred or a thousand times the right amount.
$t->throws( 'malformed dot grouping', static fn() => Keeta_Checkout_Amount::normalise( '1.2.3' ) );
$t->throws( 'malformed comma grouping', static fn() => Keeta_Checkout_Amount::normalise( '1,2,3' ) );
$t->throws( 'a four-digit group', static fn() => Keeta_Checkout_Amount::normalise( '1.2345.678' ) );
$t->throws( 'a two-digit group', static fn() => Keeta_Checkout_Amount::normalise( '12.34.56' ) );
$t->throws( 'grouping after the decimal point', static fn() => Keeta_Checkout_Amount::normalise( '12.34,56' ) );

// A single comma with exactly three digits after it cannot be resolved: it is
// either 1234 or 1.234, a factor of a thousand apart. Guessing is not acceptable.
$t->throws( 'an ambiguous single comma', static fn() => Keeta_Checkout_Amount::normalise( '1,234' ) );
$t->throws( 'an ambiguous larger comma value', static fn() => Keeta_Checkout_Amount::normalise( '12,345' ) );
// Two digits after a comma is unambiguous, because grouping is always three.
$t->same( 'two digits after a comma is a decimal', '1.23', Keeta_Checkout_Amount::normalise( '1,23' ) );
// Four is too, for the same reason.
$t->same( 'four digits after a comma is a decimal', '1.2345', Keeta_Checkout_Amount::normalise( '1,2345' ) );
// A single dot is always a decimal point: that is what WooCommerce stores.
$t->same( 'a single dot with three digits is a decimal', '1.234', Keeta_Checkout_Amount::normalise( '1.234' ) );
// A leading comma has no integer part, so there is nothing to confuse.
$t->same( 'a leading comma', '0.234', Keeta_Checkout_Amount::normalise( ',234' ) );

$t->throws( 'letters mixed in', static fn() => Keeta_Checkout_Amount::normalise( '12.5x' ) );
$t->throws( 'only separators', static fn() => Keeta_Checkout_Amount::normalise( '.,' ) );
$t->throws( 'a zero float', static fn() => Keeta_Checkout_Amount::normalise( 0.0 ) );
$t->throws( 'a negative float', static fn() => Keeta_Checkout_Amount::normalise( -1.5 ) );
$t->throws( 'an infinite float', static fn() => Keeta_Checkout_Amount::normalise( INF ) );
$t->throws( 'a NaN float', static fn() => Keeta_Checkout_Amount::normalise( NAN ) );
$t->throws( 'an array', static fn() => Keeta_Checkout_Amount::normalise( array( 1 ) ) );

// Every accepted value must satisfy the server's own grammar.
foreach ( array( '12.50', '13', '0.5', '1234.50', '007.50', '0.000000000000000001' ) as $accepted ) {
	$t->check(
		'the normalised value matches the server grammar: ' . $accepted,
		1 === preg_match( Keeta_Checkout_Amount::PATTERN, Keeta_Checkout_Amount::normalise( $accepted ) )
	);
}

/* ------------------------------------------------------- currency pairing -- */

$t->check( 'EUR with $EURC is fine', Keeta_Checkout_Amount::currency_matches_token( 'EUR', '$EURC' ) );
$t->check( 'EUR with EURC, no dollar sign', Keeta_Checkout_Amount::currency_matches_token( 'EUR', 'EURC' ) );
$t->check( 'EUR with $KBEUR is fine', Keeta_Checkout_Amount::currency_matches_token( 'EUR', '$KBEUR' ) );
$t->check( 'USD with $USDC is fine', Keeta_Checkout_Amount::currency_matches_token( 'USD', '$usdc' ) );
$t->check( 'EUR with $USDC is flagged', ! Keeta_Checkout_Amount::currency_matches_token( 'EUR', '$USDC' ) );
$t->check( 'USD with $EURC is flagged', ! Keeta_Checkout_Amount::currency_matches_token( 'USD', '$EURC' ) );
$t->check( 'EUR with $KTA is flagged', ! Keeta_Checkout_Amount::currency_matches_token( 'EUR', '$KTA' ) );
// An unknown store currency cannot be checked, so it is not flagged.
$t->check( 'an unknown currency is not flagged', Keeta_Checkout_Amount::currency_matches_token( 'XYZ', '$USDC' ) );

/* -------------------------------------------------------------- signature -- */

$secret = 'whsec_test_000000000000';
$body   = '{"id":"evt_1","type":"checkout.session.paid"}';
$now    = 1762000000;
$header = Keeta_Checkout_Signature::sign( $body, $secret, $now );

$t->check( 'the header has the expected shape', 1 === preg_match( '/^t=\d+,v1=[0-9a-f]{64}$/', $header ) );
$t->same( 'the signed payload is "t.body"', $now . '.' . $body, Keeta_Checkout_Signature::signed_payload( $now, $body ) );
$t->same( 'a delivery it just signed verifies', $now, Keeta_Checkout_Signature::verify( $body, $header, $secret, 300, $now ) );

// Tolerance, in both directions.
$t->same( 'at the edge of tolerance, late', $now, Keeta_Checkout_Signature::verify( $body, $header, $secret, 300, $now + 300 ) );
$t->same( 'at the edge of tolerance, early', $now, Keeta_Checkout_Signature::verify( $body, $header, $secret, 300, $now - 300 ) );
$t->same(
	'one second past tolerance is rejected',
	'TIMESTAMP_OUT_OF_TOLERANCE',
	$t->throws( 'too late', static fn() => Keeta_Checkout_Signature::verify( $body, $header, $secret, 300, $now + 301 ) )
);
$t->same(
	'one second before tolerance is rejected',
	'TIMESTAMP_OUT_OF_TOLERANCE',
	$t->throws( 'too early', static fn() => Keeta_Checkout_Signature::verify( $body, $header, $secret, 300, $now - 301 ) )
);

// Tampering.
$t->same(
	'a tampered body is rejected',
	'NO_MATCH',
	$t->throws( 'tampered body', static fn() => Keeta_Checkout_Signature::verify( $body . 'x', $header, $secret, 300, $now ) )
);
$t->same(
	'a re-serialised body is rejected',
	'NO_MATCH',
	$t->throws(
		're-serialised body',
		static fn() => Keeta_Checkout_Signature::verify(
			json_encode( json_decode( $body, true ), JSON_PRETTY_PRINT ),
			$header,
			$secret,
			300,
			$now
		)
	)
);
$t->same(
	'the wrong secret is rejected',
	'NO_MATCH',
	$t->throws( 'wrong secret', static fn() => Keeta_Checkout_Signature::verify( $body, $header, 'whsec_other_00000000', 300, $now ) )
);
$t->same(
	'a right-length wrong signature is rejected',
	'NO_MATCH',
	$t->throws(
		'wrong signature',
		static fn() => Keeta_Checkout_Signature::verify( $body, 't=' . $now . ',v1=' . str_repeat( 'a', 64 ), $secret, 300, $now )
	)
);

// Rotation: several secrets, any match passes.
$t->same(
	'either secret in a rotation works',
	$now,
	Keeta_Checkout_Signature::verify( $body, $header, array( 'whsec_new_000000000000', $secret ), 300, $now )
);
$t->same(
	'neither secret matching is rejected',
	'NO_MATCH',
	$t->throws(
		'rotation with no match',
		static fn() => Keeta_Checkout_Signature::verify( $body, $header, array( 'wrong_a_000000000000', 'wrong_b_000000000000' ), 300, $now )
	)
);

// Several signatures in one header, and forward compatibility.
$signature = substr( $header, strpos( $header, 'v1=' ) + 3 );
$t->same(
	'one of several signatures matching is enough',
	$now,
	Keeta_Checkout_Signature::verify( $body, 't=' . $now . ',v1=' . str_repeat( '0', 64 ) . ',v1=' . $signature, $secret, 300, $now )
);
$t->same(
	'an unknown scheme is ignored, not fatal',
	$now,
	Keeta_Checkout_Signature::verify( $body, $header . ',v2=deadbeef,foo=bar', $secret, 300, $now )
);
$t->same(
	'whitespace around the parts is tolerated',
	$now,
	Keeta_Checkout_Signature::verify( $body, ' t = ' . $now . ' , v1 = ' . $signature . ' ', $secret, 300, $now )
);

// Malformed headers.
foreach ( array( null, '', '   ' ) as $missing ) {
	$t->same(
		'a missing header is rejected',
		'MALFORMED_HEADER',
		$t->throws( 'missing header', static fn() => Keeta_Checkout_Signature::verify( $body, $missing, $secret, 300, $now ) )
	);
}
$t->same(
	'garbage is rejected',
	'MALFORMED_HEADER',
	$t->throws( 'garbage', static fn() => Keeta_Checkout_Signature::verify( $body, 'garbage', $secret, 300, $now ) )
);
$t->same(
	'a non-numeric timestamp is rejected',
	'MALFORMED_HEADER',
	$t->throws( 'bad timestamp', static fn() => Keeta_Checkout_Signature::verify( $body, 't=later,v1=abc', $secret, 300, $now ) )
);
$t->same(
	'a timestamp with no signature is rejected',
	'NO_SIGNATURES',
	$t->throws( 'no signature', static fn() => Keeta_Checkout_Signature::verify( $body, 't=' . $now, $secret, 300, $now ) )
);
$t->same(
	'a signature with no timestamp is rejected',
	'MALFORMED_HEADER',
	$t->throws( 'no timestamp', static fn() => Keeta_Checkout_Signature::verify( $body, 'v1=' . $signature, $secret, 300, $now ) )
);

/* ------------------------------------------- the two languages must agree -- */

$fixtures_path = __DIR__ . '/fixtures.json';
if ( is_readable( $fixtures_path ) ) {
	$fixtures = json_decode( (string) file_get_contents( $fixtures_path ), true );

	if ( ! is_array( $fixtures ) || array() === $fixtures ) {
		$t->check( 'fixtures.json is usable', false, 'it decoded to nothing' );
	} else {
		foreach ( $fixtures as $index => $fixture ) {
			$name = sprintf( 'fixture %d (%s)', (int) $index, (string) ( $fixture['name'] ?? '?' ) );

			if ( true === ( $fixture['valid'] ?? false ) ) {
				$t->same(
					$name . ' verifies',
					(int) $fixture['timestamp'],
					Keeta_Checkout_Signature::verify(
						(string) $fixture['rawBody'],
						(string) $fixture['header'],
						(string) $fixture['secret'],
						300,
						(int) $fixture['timestamp']
					)
				);
				// And the PHP signer reproduces the TypeScript one byte for byte.
				$t->same(
					$name . ' re-signs identically',
					(string) $fixture['header'],
					Keeta_Checkout_Signature::sign(
						(string) $fixture['rawBody'],
						(string) $fixture['secret'],
						(int) $fixture['timestamp']
					)
				);
			} else {
				$t->check(
					$name . ' is rejected',
					null !== $t->throws(
						$name,
						static fn() => Keeta_Checkout_Signature::verify(
							(string) $fixture['rawBody'],
							(string) $fixture['header'],
							(string) $fixture['secret'],
							300,
							(int) $fixture['timestamp']
						)
					)
				);
			}
		}
		printf( "checked %d cross-language fixtures\n", count( $fixtures ) );
	}
} else {
	fwrite( STDERR, "note: fixtures.json is missing, so cross-language agreement was not checked\n" );
	fwrite( STDERR, "      regenerate it with: pnpm tsx tools/webhook-fixtures.ts\n" );
}

exit( $t->report() );
